mapper.select:
SELECT embedding_model, active_index_version
FROM kb_knowledge_index_active
WHERE tenant_id = #{tenantId}
  AND knowledge_base_id = #{knowledgeBaseId}

WITH , scored AS ( SELECT , 1 - (candidate.embedding <=> CAST(#{embedding} AS vector)) AS score FROM kb_document_chunk chunk JOIN kb_document_chunk_embedding candidate ON candidate.tenant_id = chunk.tenant_id AND candidate.knowledge_base_id = chunk.knowledge_base_id AND candidate.document_id = chunk.document_id AND candidate.chunk_id = chunk.id AND candidate.embedding_model = #{embeddingModel} AND candidate.index_version = #{indexVersion} WHERE chunk.tenant_id = #{tenantId} AND chunk.knowledge_base_id IN
#{knowledgeBaseId}
AND chunk.status = 'ACTIVE' AND chunk.deleted_at IS NULL AND candidate.embedding IS NOT NULL
) SELECT scored.*, ROW_NUMBER() OVER (ORDER BY score DESC, id ASC) AS rank FROM scored WHERE score >= #{scoreThreshold} ORDER BY score DESC, id ASC LIMIT #{topK}

WITH , query AS ( SELECT plainto_tsquery('simple', #{query}) AS ts_query ), scored AS ( SELECT , LEAST(1.0, ts_rank_cd(to_tsvector('simple', content), query.ts_query) * 10) AS score FROM kb_document_chunk chunk JOIN kb_document_chunk_embedding candidate ON candidate.tenant_id = chunk.tenant_id AND candidate.knowledge_base_id = chunk.knowledge_base_id AND candidate.document_id = chunk.document_id AND candidate.chunk_id = chunk.id AND candidate.embedding_model = #{embeddingModel} AND candidate.index_version = #{indexVersion} CROSS JOIN query WHERE chunk.tenant_id = #{tenantId} AND chunk.knowledge_base_id IN
#{knowledgeBaseId}
AND chunk.status = 'ACTIVE' AND chunk.deleted_at IS NULL AND candidate.embedding IS NOT NULL
AND to_tsvector('simple', chunk.content) @@ query.ts_query ) SELECT scored.*, ROW_NUMBER() OVER (ORDER BY score DESC, id ASC) AS rank FROM scored ORDER BY score DESC, id ASC LIMIT #{topK}
